-- Hand-written (design doc §10.4).

-- Active statuses have no end time; ended statuses always do.
ALTER TABLE "Assignment"
  ADD CONSTRAINT "Assignment_status_ended_check"
  CHECK (("status" IN ('CLAIMED', 'IN_PROGRESS')) = ("endedAt" IS NULL));

-- At most one active assignment per report. Two simultaneous claims: one
-- insert succeeds, the other fails with 23505 (unique_violation).
CREATE UNIQUE INDEX "Assignment_one_active_per_report"
  ON "Assignment" ("reportId") WHERE "endedAt" IS NULL;

